using System.Runtime.InteropServices;
using System.Runtime.Versioning;
using System.Security.AccessControl;
using System.Security.Cryptography;
using System.Security.Principal;

namespace Mila.Windows.Interop;

/// <summary>
/// X25519 poke-decryption key custody for one Windows user (ADR-0235 decision 3).
/// Each deployment gets its own key pair, generated by CNG (curve25519), sealed
/// with DPAPI in user scope, and stored in an owner-only directory. Only the
/// public key leaves this class.
/// </summary>
/// <remarks>
/// @cc [owner:ghuntley,label:security;privacy] mila-windows-poke-key-custody
/// The private key MUST exist on disk only as a DPAPI (CurrentUser) blob bound to
/// its deployment, in a directory and file whose protected DACL grants only the
/// current user and SYSTEM. A file or directory whose DACL admits anyone else, or
/// a blob that DPAPI does not unseal to this store's format, MUST NOT be used and
/// MUST NOT be silently replaced: the key is reported unavailable. Public keys
/// are RFC 7748 little-endian u-coordinates, unpadded base64url (43 characters).
/// </remarks>
[SupportedOSPlatform("windows")]
internal sealed class MilaWindowsPokeKeyStore : IMilaPokeKeySource
{
    private const int KeyBytes = 32;
    private static readonly byte[] Magic = "mila-poke-x25519-v1"u8.ToArray();
    private readonly string directory;

    internal MilaWindowsPokeKeyStore(string? directory = null) =>
        this.directory = directory ?? Path.Combine(
            Environment.GetFolderPath(Environment.SpecialFolder.LocalApplicationData), "Mila", "poke-keys");

    /// <summary>The deployment's poke public key, created on first use; null when custody is unavailable.</summary>
    public string? PublicKey(string deployment)
    {
        try { return Base64Url(LoadOrCreate(deployment).Public); }
        catch (Exception error) when (error is CryptographicException or IOException or UnauthorizedAccessException
            or ArgumentException or InvalidDataException or PlatformNotSupportedException)
        {
            return null;
        }
    }

    /// <summary>Loads (or creates) the deployment's pair. The caller owns the returned private bytes and must clear them.</summary>
    internal (byte[] Private, byte[] Public) LoadOrCreate(string deployment)
    {
        string path = PathFor(deployment);
        EnsureOwnerOnlyDirectory(directory);
        if (File.Exists(path))
        {
            RequireOwnerOnly(new FileInfo(path).GetAccessControl());
            byte[] sealedBlob = File.ReadAllBytes(path);
            if (sealedBlob.Length is 0 or > 4096) throw new InvalidDataException("poke key blob bounds");
            return Unseal(sealedBlob, deployment);
        }
        (byte[] privateKey, byte[] publicKey) = MilaX25519.Generate();
        byte[] blob = Seal(privateKey, publicKey, deployment);
        string temporary = path + ".new";
        try
        {
            FileSecurity security = new();
            security.SetSecurityDescriptorSddlForm(OwnerOnlySddl(isDirectory: false));
            using (FileStream stream = new FileInfo(temporary).Create(FileMode.CreateNew, FileSystemRights.Write,
                       FileShare.None, 4096, FileOptions.WriteThrough, security))
            {
                stream.Write(blob);
                stream.Flush(true);
            }
            // Never replace a key another process created first.
            File.Move(temporary, path, overwrite: false);
        }
        catch (IOException) when (File.Exists(path))
        {
            Array.Clear(privateKey);
            return LoadOrCreate(deployment);
        }
        finally
        {
            if (File.Exists(temporary)) File.Delete(temporary);
        }
        return (privateKey, publicKey);
    }

    private string PathFor(string deployment)
    {
        // DeviceKey's canonical host rule doubles as a safe file name.
        string name = DeviceKey.KeyName(deployment)["dev.overalls.mila.device.".Length..];
        return Path.Combine(directory, name + ".poke");
    }

    private static byte[] Entropy(string deployment) =>
        System.Text.Encoding.UTF8.GetBytes("dev.overalls.mila.poke.v1|" + deployment);

    private static byte[] Seal(byte[] privateKey, byte[] publicKey, string deployment)
    {
        byte[] plain = [.. Magic, .. privateKey, .. publicKey];
        try { return MilaDpapi.Protect(plain, Entropy(deployment)); }
        finally { Array.Clear(plain); }
    }

    private static (byte[] Private, byte[] Public) Unseal(byte[] blob, string deployment)
    {
        byte[] plain = MilaDpapi.Unprotect(blob, Entropy(deployment));
        try
        {
            if (plain.Length != Magic.Length + 2 * KeyBytes || !plain.AsSpan(0, Magic.Length).SequenceEqual(Magic))
                throw new InvalidDataException("poke key blob shape");
            // DPAPI authenticates the blob, so the stored pair is the pair this store wrote.
            byte[] privateKey = plain[Magic.Length..(Magic.Length + KeyBytes)];
            byte[] publicKey = plain[(Magic.Length + KeyBytes)..];
            return (privateKey, publicKey);
        }
        finally { Array.Clear(plain); }
    }

    /// <summary>Protected DACL: full control for the current user and SYSTEM only.</summary>
    internal static string OwnerOnlySddl(bool isDirectory)
    {
        string user = WindowsIdentity.GetCurrent().User?.Value ?? throw new UnauthorizedAccessException("no user SID");
        string inherit = isDirectory ? "OICI" : "";
        return $"D:P(A;{inherit};FA;;;{user})(A;{inherit};FA;;;SY)";
    }

    private static void EnsureOwnerOnlyDirectory(string path)
    {
        if (!Directory.Exists(path))
        {
            if (Path.GetDirectoryName(path) is { Length: > 0 } parent) Directory.CreateDirectory(parent);
            DirectorySecurity security = new();
            security.SetSecurityDescriptorSddlForm(OwnerOnlySddl(isDirectory: true));
            new DirectoryInfo(path).Create(security);
        }
        RequireOwnerOnly(new DirectoryInfo(path).GetAccessControl());
    }

    /// <summary>Refuses a protected-or-not DACL that grants anything to a SID other than the user or SYSTEM.</summary>
    internal static void RequireOwnerOnly(FileSystemSecurity security)
    {
        SecurityIdentifier user = WindowsIdentity.GetCurrent().User ?? throw new UnauthorizedAccessException("no user SID");
        SecurityIdentifier system = new(WellKnownSidType.LocalSystemSid, null);
        if (!security.AreAccessRulesProtected) throw new UnauthorizedAccessException("poke key ACL inherits");
        foreach (FileSystemAccessRule rule in security.GetAccessRules(true, true, typeof(SecurityIdentifier)))
        {
            if (rule.AccessControlType == AccessControlType.Allow &&
                rule.IdentityReference is SecurityIdentifier sid && sid != user && sid != system)
                throw new UnauthorizedAccessException("poke key ACL admits another principal");
        }
    }

    internal static string Base64Url(ReadOnlySpan<byte> bytes) =>
        Convert.ToBase64String(bytes).TrimEnd('=').Replace('+', '-').Replace('/', '_');
}

/// <summary>
/// X25519 through CNG's curve25519. .NET's ECParameters carry big-endian
/// integers, so keys are reversed to and from RFC 7748's little-endian encoding.
/// </summary>
[SupportedOSPlatform("windows")]
internal static class MilaX25519
{
    private static ECCurve Curve => ECCurve.CreateFromFriendlyName("curve25519");

    internal static (byte[] Private, byte[] Public) Generate()
    {
        using ECDiffieHellman key = ECDiffieHellman.Create(Curve);
        ECParameters parameters = key.ExportParameters(includePrivateParameters: true);
        try
        {
            if (parameters.D is not { Length: 32 } d || parameters.Q.X is not { Length: 32 } x)
                throw new CryptographicException("curve25519 key shape");
            return (Reversed(d), Reversed(x));
        }
        finally { if (parameters.D is { } secret) Array.Clear(secret); }
    }

    /// <summary>The raw X25519 shared secret (RFC 7748 encoding) for this key pair and a peer public key.</summary>
    internal static byte[] Agree(ReadOnlySpan<byte> privateKey, ReadOnlySpan<byte> publicKey, ReadOnlySpan<byte> peerPublic)
    {
        if (privateKey.Length != 32 || publicKey.Length != 32 || peerPublic.Length != 32)
            throw new CryptographicException("curve25519 key length");
        byte[] d = Reversed(privateKey);
        try
        {
            using ECDiffieHellman key = ECDiffieHellman.Create(new ECParameters
            {
                Curve = Curve, D = d, Q = new ECPoint { X = Reversed(publicKey), Y = new byte[32] },
            });
            using ECDiffieHellman peer = ECDiffieHellman.Create(new ECParameters
            {
                Curve = Curve, Q = new ECPoint { X = Reversed(peerPublic), Y = new byte[32] },
            });
            return Reversed(key.DeriveRawSecretAgreement(peer.PublicKey));
        }
        finally { Array.Clear(d); }
    }

    private static byte[] Reversed(ReadOnlySpan<byte> value)
    {
        byte[] copy = value.ToArray();
        Array.Reverse(copy);
        return copy;
    }
}

/// <summary>User-scope DPAPI through crypt32, avoiding an extra package in the locked restore.</summary>
[SupportedOSPlatform("windows")]
internal static partial class MilaDpapi
{
    [StructLayout(LayoutKind.Sequential)]
    private struct DataBlob
    {
        internal int Size;
        internal IntPtr Data;
    }

    private const int UiForbidden = 0x1;

    [LibraryImport("crypt32.dll", EntryPoint = "CryptProtectData", SetLastError = true)]
    [return: MarshalAs(UnmanagedType.Bool)]
    private static partial bool CryptProtectData(
        ref DataBlob input, IntPtr description, ref DataBlob entropy, IntPtr reserved, IntPtr prompt, int flags, out DataBlob output);

    [LibraryImport("crypt32.dll", EntryPoint = "CryptUnprotectData", SetLastError = true)]
    [return: MarshalAs(UnmanagedType.Bool)]
    private static partial bool CryptUnprotectData(
        ref DataBlob input, IntPtr description, ref DataBlob entropy, IntPtr reserved, IntPtr prompt, int flags, out DataBlob output);

    [LibraryImport("kernel32.dll")]
    private static partial IntPtr LocalFree(IntPtr memory);

    internal static byte[] Protect(byte[] plain, byte[] entropy) => Transform(plain, entropy, protect: true);
    internal static byte[] Unprotect(byte[] blob, byte[] entropy) => Transform(blob, entropy, protect: false);

    private static unsafe byte[] Transform(byte[] input, byte[] entropy, bool protect)
    {
        fixed (byte* inputPointer = input)
        fixed (byte* entropyPointer = entropy)
        {
            DataBlob data = new() { Size = input.Length, Data = (IntPtr)inputPointer };
            DataBlob salt = new() { Size = entropy.Length, Data = (IntPtr)entropyPointer };
            bool ok = protect
                ? CryptProtectData(ref data, IntPtr.Zero, ref salt, IntPtr.Zero, IntPtr.Zero, UiForbidden, out DataBlob output)
                : CryptUnprotectData(ref data, IntPtr.Zero, ref salt, IntPtr.Zero, IntPtr.Zero, UiForbidden, out output);
            if (!ok) throw new CryptographicException(Marshal.GetLastPInvokeError());
            try
            {
                byte[] result = new byte[output.Size];
                Marshal.Copy(output.Data, result, 0, output.Size);
                return result;
            }
            finally
            {
                if (!protect) new Span<byte>((void*)output.Data, output.Size).Clear();
                LocalFree(output.Data);
            }
        }
    }
}
